        "code": "package main\n\nimport (\n\t\"encoding/json\"\n\t\"fmt\"\n\t\"os\"\n)\n\n// Finding describes one vulnerability. Struct tags set the JSON field names.\ntype Finding struct {\n\tID       string  `json:\"id\"`\n\tPackage  string  `json:\"package\"`\n\tSeverity string  `json:\"severity\"`\n\tCVSS     float64 `json:\"cvss\"`\n\tFixed    bool    `json:\"fixed\"`\n}\n\n// IsBlocking has a value receiver: it only reads the struct\nfunc (f Finding) IsBlocking() bool {\n\treturn !f.Fixed && f.CVSS >= 7.0\n}\n\n// MarkFixed has a pointer receiver: it modifies the original struct\nfunc (f *Finding) MarkFixed() {\n\tf.Fixed = true\n}\n\nfunc main() {\n\tfindings := []Finding{\n\t\t{ID: \"CVE-2024-3094\", Package: \"xz-utils\", Severity: \"CRITICAL\", CVSS: 10.0},\n\t\t{ID: \"CVE-2023-44487\", Package: \"golang.org/x/net\", Severity: \"HIGH\", CVSS: 7.5},\n\t\t{ID: \"CVE-2023-2650\", Package: \"openssl\", Severity: \"MEDIUM\", CVSS: 6.5},\n\t}\n\n\t// findings[1] is the real element of the slice, so the change is kept\n\tfindings[1].MarkFixed()\n\n\tblocking := 0\n\tfor _, f := range findings {\n\t\tif f.IsBlocking() {\n\t\t\tblocking++\n\t\t}\n\t}\n\tfmt.Println(\"blocking findings:\", blocking)\n\n\t// Encode the first finding as indented JSON on standard output\n\tenc := json.NewEncoder(os.Stdout)\n\tenc.SetIndent(\"\", \"  \")\n\tif err := enc.Encode(findings[0]); err != nil {\n\t\tfmt.Fprintln(os.Stderr, \"encode:\", err)\n\t\tos.Exit(1)\n\t}\n}\n",
