        "code": "package main\n\nimport (\n\t\"errors\"\n\t\"fmt\"\n\t\"slices\"\n)\n\n// Config is the server configuration under audit\ntype Config struct {\n\tSSHRootLogin  bool\n\tTLSMinVersion string\n\tOpenPorts     []int\n}\n\n// Check is satisfied by ANY type that has these two methods.\n// There is no \"implements\" keyword in Go.\ntype Check interface {\n\tName() string\n\tRun(cfg Config) error\n}\n\ntype rootLoginCheck struct{}\n\nfunc (rootLoginCheck) Name() string { return \"ssh-root-login\" }\nfunc (rootLoginCheck) Run(cfg Config) error {\n\tif cfg.SSHRootLogin {\n\t\treturn errors.New(\"root login over SSH is enabled\")\n\t}\n\treturn nil\n}\n\ntype tlsCheck struct{ minimum string }\n\nfunc (c tlsCheck) Name() string { return \"tls-min-version\" }\nfunc (c tlsCheck) Run(cfg Config) error {\n\t// String comparison is enough for \"1.0\", \"1.1\", \"1.2\", \"1.3\"\n\tif cfg.TLSMinVersion < c.minimum {\n\t\treturn fmt.Errorf(\"TLS %s is accepted, want at least %s\", cfg.TLSMinVersion, c.minimum)\n\t}\n\treturn nil\n}\n\ntype forbiddenPortCheck struct{ forbidden []int }\n\nfunc (c forbiddenPortCheck) Name() string { return \"forbidden-ports\" }\nfunc (c forbiddenPortCheck) Run(cfg Config) error {\n\tfor _, port := range cfg.OpenPorts {\n\t\tif slices.Contains(c.forbidden, port) {\n\t\t\treturn fmt.Errorf(\"port %d must be closed\", port)\n\t\t}\n\t}\n\treturn nil\n}\n\nfunc main() {\n\tcfg := Config{SSHRootLogin: true, TLSMinVersion: \"1.2\", OpenPorts: []int{22, 23, 443}}\n\n\t// The engine only knows the interface, not the concrete types\n\tchecks := []Check{\n\t\trootLoginCheck{},\n\t\ttlsCheck{minimum: \"1.2\"},\n\t\tforbiddenPortCheck{forbidden: []int{21, 23, 3389}},\n\t}\n\n\tfailed := 0\n\tfor _, c := range checks {\n\t\tif err := c.Run(cfg); err != nil {\n\t\t\tfailed++\n\t\t\tfmt.Printf(\"FAIL %-16s %v\\n\", c.Name(), err)\n\t\t\tcontinue\n\t\t}\n\t\tfmt.Printf(\"PASS %s\\n\", c.Name())\n\t}\n\tfmt.Printf(\"%d/%d checks failed\\n\", failed, len(checks))\n}\n",
