        "kind": "neutral",
        "code": "package main\n\nimport (\n\t\"fmt\"\n\t\"net\"\n\t\"strconv\"\n\t\"time\"\n)\n\nfunc main() {\n\t// Only scan machines you own or are explicitly authorised to test\n\tconst host = \"127.0.0.1\"\n\tstart := time.Now()\n\n\tfor port := 1; port <= 1024; port++ {\n\t\t// JoinHostPort builds \"127.0.0.1:22\" and also handles IPv6 correctly\n\t\taddress := net.JoinHostPort(host, strconv.Itoa(port))\n\n\t\t// Give up after 500 ms: a filtered port never answers\n\t\tconn, err := net.DialTimeout(\"tcp\", address, 500*time.Millisecond)\n\t\tif err != nil {\n\t\t\tcontinue // closed or filtered\n\t\t}\n\t\tconn.Close()\n\t\tfmt.Printf(\"%d/tcp open\\n\", port)\n\t}\n\n\tfmt.Printf(\"1024 ports scanned in %s\\n\", time.Since(start).Round(time.Millisecond))\n}\n",
