        "code": "package main\n\nimport (\n\t\"context\"\n\t\"fmt\"\n\t\"net\"\n\t\"os\"\n\t\"os/signal\"\n\t\"slices\"\n\t\"strconv\"\n\t\"sync\"\n\t\"time\"\n)\n\n// scanPort reports whether a TCP port accepts connections\nfunc scanPort(ctx context.Context, host string, port int, timeout time.Duration) bool {\n\tdialer := net.Dialer{Timeout: timeout}\n\t// DialContext returns at once when ctx is cancelled (Ctrl+C or deadline)\n\tconn, err := dialer.DialContext(ctx, \"tcp\", net.JoinHostPort(host, strconv.Itoa(port)))\n\tif err != nil {\n\t\treturn false\n\t}\n\tconn.Close()\n\treturn true\n}\n\nfunc main() {\n\tconst (\n\t\thost      = \"127.0.0.1\" // scan only hosts you own or are authorised to test\n\t\tfirstPort = 1\n\t\tlastPort  = 1024\n\t\tworkers   = 100 // maximum number of simultaneous connections\n\t\ttimeout   = 500 * time.Millisecond\n\t)\n\n\t// Cancelled on Ctrl+C, and in any case after 30 seconds\n\tctx, stop := signal.NotifyContext(context.Background(), os.Interrupt)\n\tdefer stop()\n\tctx, cancel := context.WithTimeout(ctx, 30*time.Second)\n\tdefer cancel()\n\n\tstart := time.Now()\n\tports := make(chan int)   // work to do\n\tresults := make(chan int) // open ports\n\n\t// Start a fixed number of workers\n\tvar wg sync.WaitGroup\n\tfor range workers {\n\t\twg.Add(1)\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tfor port := range ports { // ends when \"ports\" is closed\n\t\t\t\tif scanPort(ctx, host, port, timeout) {\n\t\t\t\t\tresults <- port\n\t\t\t\t}\n\t\t\t}\n\t\t}()\n\t}\n\n\t// Producer: feed the workers, stop early if the context is cancelled\n\tgo func() {\n\t\tdefer close(ports)\n\t\tfor port := firstPort; port <= lastPort; port++ {\n\t\t\tselect {\n\t\t\tcase ports <- port:\n\t\t\tcase <-ctx.Done():\n\t\t\t\treturn\n\t\t\t}\n\t\t}\n\t}()\n\n\t// Close \"results\" once every worker has finished\n\tgo func() {\n\t\twg.Wait()\n\t\tclose(results)\n\t}()\n\n\t// Collector: the main goroutine is the only one touching \"open\"\n\tvar open []int\n\tfor port := range results {\n\t\topen = append(open, port)\n\t}\n\tslices.Sort(open)\n\n\tfor _, port := range open {\n\t\tfmt.Printf(\"%d/tcp open\\n\", port)\n\t}\n\tfmt.Printf(\"%d ports scanned in %s with %d workers\\n\",\n\t\tlastPort-firstPort+1, time.Since(start).Round(time.Millisecond), workers)\n\n\tif ctx.Err() != nil {\n\t\tfmt.Fprintln(os.Stderr, \"scan interrupted:\", ctx.Err())\n\t\tos.Exit(1)\n\t}\n}\n",
        "output": "22/tcp open\n80/tcp open\n1024 ports scanned in 12ms with 100 workers\n",
        "note": {
          "fr": "Jamais plus de 100 connexions à la fois, pas de `Mutex` (seule la goroutine principale écrit dans `open`), des résultats triés, et un Ctrl+C arrête tout proprement. Contre une cible filtrée, le temps passe de 8 minutes à environ 5 secondes. `for range workers` (boucle sur un entier) demande Go 1.22 ou plus récent.",
          "en": "Never more than 100 connections at once, no `Mutex` (only the main goroutine writes to `open`), sorted results, and Ctrl+C stops everything cleanly. Against a filtered target, the time drops from 8 minutes to about 5 seconds. `for range workers` (looping over an integer) requires Go 1.22 or later."
        }
